-- FCDex schema (Prisma mirror of BallsDex DDL + additive columns).
-- Regenerate by hand when prisma/schema.prisma changes; applied by `bun run db:push`.

CREATE TABLE "public"."player" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "discord_id" bigint NOT NULL,
    "donation_policy" integer NOT NULL DEFAULT 0,
    "privacy_policy" integer NOT NULL DEFAULT 0,
    "mention_policy" integer NOT NULL DEFAULT 0,
    "friend_policy" integer NOT NULL DEFAULT 0,
    "extra_data" jsonb NOT NULL DEFAULT '{}',
    "trade_cooldown_policy" integer NOT NULL DEFAULT 0,
    "money" bigint NOT NULL DEFAULT 0,
    CONSTRAINT "player_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "player_discord_id_key" ON "public"."player"("discord_id");

CREATE TABLE "public"."ball" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "country" varchar(48) NOT NULL,
    "health" integer NOT NULL,
    "attack" integer NOT NULL,
    "rarity" double precision NOT NULL,
    "emoji_id" bigint NOT NULL,
    "wild_card" varchar(200) NOT NULL,
    "collection_card" varchar(200) NOT NULL,
    "credits" varchar(64) NOT NULL,
    "capacity_name" varchar(64) NOT NULL,
    "capacity_description" varchar(256) NOT NULL,
    "capacity_logic" jsonb NOT NULL,
    "enabled" boolean NOT NULL DEFAULT true,
    "short_name" varchar(24),
    "catch_names" text,
    "tradeable" boolean NOT NULL DEFAULT true,
    "created_at" timestamptz,
    "translations" text,
    "economy_id" bigint,
    "regime_id" bigint NOT NULL,
    CONSTRAINT "ball_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ball_country_key" ON "public"."ball"("country");
CREATE INDEX "ball_enabled_rarity_idx" ON "public"."ball"("enabled", "rarity");

CREATE TABLE "public"."special" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(64) NOT NULL,
    "catch_phrase" varchar(128),
    "start_date" timestamptz,
    "end_date" timestamptz,
    "rarity" double precision NOT NULL,
    "emoji" varchar(20),
    "background" varchar(200),
    "tradeable" boolean NOT NULL DEFAULT true,
    "hidden" boolean NOT NULL DEFAULT false,
    "credits" varchar(64),
    CONSTRAINT "special_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "special_name_key" ON "public"."special"("name");

CREATE TABLE "public"."ballinstance" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "catch_date" timestamptz NOT NULL,
    "health_bonus" integer NOT NULL DEFAULT 0,
    "attack_bonus" integer NOT NULL DEFAULT 0,
    "favorite" boolean NOT NULL DEFAULT false,
    "server_id" bigint,
    "tradeable" boolean NOT NULL DEFAULT true,
    "extra_data" jsonb NOT NULL DEFAULT '{}',
    "locked" timestamptz,
    "spawned_time" timestamptz,
    "ball_id" bigint NOT NULL,
    "player_id" bigint NOT NULL,
    "trade_player_id" bigint,
    "special_id" bigint,
    "deleted" boolean NOT NULL DEFAULT false,
    CONSTRAINT "ballinstance_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "ballinstance_player_id_favorite_idx" ON "public"."ballinstance"("player_id", "favorite");
CREATE INDEX "ballinstance_ball_id_idx" ON "public"."ballinstance"("ball_id");

CREATE TABLE "public"."trade" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "date" timestamptz NOT NULL DEFAULT now(),
    "player1_id" bigint NOT NULL,
    "player2_id" bigint NOT NULL,
    "player1_money" bigint NOT NULL DEFAULT 0,
    "player2_money" bigint NOT NULL DEFAULT 0,
    "status" text,
    "expires_at" timestamptz,
    "resolved_at" timestamptz,
    CONSTRAINT "trade_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "public"."tradeobject" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ballinstance_id" bigint NOT NULL,
    "player_id" bigint NOT NULL,
    "trade_id" bigint NOT NULL,
    CONSTRAINT "tradeobject_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "tradeobject_trade_id_idx" ON "public"."tradeobject"("trade_id");

CREATE TABLE "public"."guildconfig" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "guild_id" bigint NOT NULL,
    "spawn_channel" bigint,
    "enabled" boolean NOT NULL DEFAULT true,
    "silent" boolean NOT NULL DEFAULT false,
    "admin_command_synced" boolean NOT NULL DEFAULT false,
    "manual_drop_enabled" boolean NOT NULL DEFAULT true,
    "tips_enabled" boolean NOT NULL DEFAULT true,
    CONSTRAINT "guildconfig_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "guildconfig_guild_id_key" ON "public"."guildconfig"("guild_id");

CREATE TABLE "public"."blacklistedid" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "discord_id" bigint NOT NULL,
    "reason" text,
    "date" timestamptz,
    "moderator_id" bigint,
    CONSTRAINT "blacklistedid_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "blacklistedid_discord_id_key" ON "public"."blacklistedid"("discord_id");

ALTER TABLE "public"."ballinstance" ADD CONSTRAINT "ballinstance_ball_id_fkey" FOREIGN KEY ("ball_id") REFERENCES "public"."ball"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "public"."ballinstance" ADD CONSTRAINT "ballinstance_player_id_fkey" FOREIGN KEY ("player_id") REFERENCES "public"."player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."ballinstance" ADD CONSTRAINT "ballinstance_special_id_fkey" FOREIGN KEY ("special_id") REFERENCES "public"."special"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "public"."trade" ADD CONSTRAINT "trade_player1_id_fkey" FOREIGN KEY ("player1_id") REFERENCES "public"."player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."trade" ADD CONSTRAINT "trade_player2_id_fkey" FOREIGN KEY ("player2_id") REFERENCES "public"."player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."tradeobject" ADD CONSTRAINT "tradeobject_ballinstance_id_fkey" FOREIGN KEY ("ballinstance_id") REFERENCES "public"."ballinstance"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."tradeobject" ADD CONSTRAINT "tradeobject_player_id_fkey" FOREIGN KEY ("player_id") REFERENCES "public"."player"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public"."tradeobject" ADD CONSTRAINT "tradeobject_trade_id_fkey" FOREIGN KEY ("trade_id") REFERENCES "public"."trade"("id") ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE IF NOT EXISTS "public"."blacklistedguild" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "discord_id" bigint NOT NULL,
    "reason" text,
    "date" timestamptz,
    "moderator_id" bigint,
    CONSTRAINT "blacklistedguild_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "blacklistedguild_discord_id_key" ON "public"."blacklistedguild"("discord_id");

CREATE TABLE IF NOT EXISTS "public"."spawnwave" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "guild_id" bigint NOT NULL,
    "wave_key" varchar(64) NOT NULL,
    "rarity_floor" double precision NOT NULL,
    "rarity_ceiling" double precision NOT NULL,
    "size" integer NOT NULL,
    "status" varchar(16) NOT NULL DEFAULT 'active',
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "ended_at" timestamptz,
    CONSTRAINT "spawnwave_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "spawnwave_wave_key_key" ON "public"."spawnwave"("wave_key");
CREATE INDEX IF NOT EXISTS "spawnwave_guild_id_created_at_idx" ON "public"."spawnwave"("guild_id", "created_at");

CREATE TABLE IF NOT EXISTS "public"."spawnwaveentry" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "wave_id" bigint NOT NULL,
    "ball_id" bigint NOT NULL,
    "special_id" bigint,
    "spawn_key" varchar(64),
    "instance_id" bigint,
    "reward" bigint NOT NULL DEFAULT 0,
    "caught" boolean NOT NULL DEFAULT false,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "spawnwaveentry_pkey" PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "spawnwaveentry_wave_id_idx" ON "public"."spawnwaveentry"("wave_id");

ALTER TABLE "public"."spawnwaveentry" ADD CONSTRAINT "spawnwaveentry_wave_id_fkey" FOREIGN KEY ("wave_id") REFERENCES "public"."spawnwave"("id") ON DELETE CASCADE ON UPDATE CASCADE;
